package com.sanctuarygames.createtransit;
import com.sanctuarygames.createtransit.elevator.*;import com.sanctuarygames.createtransit.elevator.model.*;
import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.world.level.block.Blocks;
import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.ClientTickEvent;
import java.util.concurrent.CompletableFuture;
@EventBusSubscriber(modid=CreateTransit.MOD_ID,value=Dist.CLIENT)
public final class HallwayVisualValidation {
 private static int ticks,index=-1,applied=-1;private static CompletableFuture<Void> pending;private static BlockPos driver=new BlockPos(0,128,0);private static BlockPos call;
 private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!Boolean.getBoolean("transit.hallwayValidation"))return;var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;ticks++;
 if(index==-1){index=0;pending=CompletableFuture.runAsync(()->{
  var level=mc.getSingleplayerServer().overworld();for(var e:level.getEntitiesOfClass(ModelCabinEntity.class,new net.minecraft.world.phys.AABB(-20,120,-20,20,160,20)))e.discard();
  for(int x=-7;x<=7;x++)for(int y=127;y<=145;y++)for(int z=-8;z<=5;z++)level.setBlock(new BlockPos(x,y,z),(y==127?Blocks.SMOOTH_STONE:Blocks.AIR).defaultBlockState(),3);
  level.setDayTime(6000);level.setWeatherParameters(100000,0,false,false);
  level.setBlock(driver,ElevatorRegistry.DRIVE.get().defaultBlockState().setValue(ElevatorPartBlock.FACING,Direction.SOUTH),3);var d=(ElevatorDriveEntity)level.getBlockEntity(driver);d.onLoad();
  for(int y=129;y<=141;y++){var pos=driver.atY(y);level.setBlock(pos,(y==129||y==135||y==141?ElevatorRegistry.FLOOR_MARKER_RAIL:ElevatorRegistry.GUIDE_RAIL).get().defaultBlockState().setValue(ElevatorPartBlock.FACING,Direction.SOUTH),3);((ElevatorPartEntity)level.getBlockEntity(pos)).onLoad();}
  check(d.configureModel("compact","true")&&d.configureModel("railMount","true")&&d.configureModel("kit3","true"),"Fixture configuration");d.rescan();
  var player=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);for(var floor:d.floorList())check(d.installModelLanding(player,floor.y()),"Fixture landing");check(d.activateModel(),"Fixture activation");
  var cabin=d.model().entity();var eye=cabin.world(1.5,.125,-4.5);player.connection.teleport(eye.x,eye.y,eye.z,0,-6);
  var base=d.model().landingPosition(128,false);call=base.offset(3,1,0);level.setBlock(call,ElevatorRegistry.FLOOR_CALL.get().defaultBlockState().setValue(ElevatorPartBlock.FACING,Direction.NORTH),3);var be=(ElevatorPartEntity)level.getBlockEntity(call);be.toggleMarker(driver.above());ElevatorCallBlock.refreshPanel(level,call,be);check(be.callLayout==1,"Bottom physical call panel is Up only");System.out.println("V15_VISUAL landing="+base+" call="+call+" camera="+eye);
 },mc.getSingleplayerServer());return;}
 if(pending!=null&&!pending.isDone())return;if(pending!=null){pending.join();pending=null;ticks=0;}
 if(ticks==1&&index<6&&applied!=index){applied=index;String style=CabinConfiguration.IndicatorStyle.values()[index].name();pending=CompletableFuture.runAsync(()->{var d=(ElevatorDriveEntity)mc.getSingleplayerServer().overworld().getBlockEntity(driver);check(d.configureModel("indicatorStyle",style)&&d.configureModel("sideIndicatorStyle",style),"Style applied "+style);},mc.getSingleplayerServer());ticks=2;}
 else if(ticks==30&&index<6){String name="V15-hallway-"+CabinConfiguration.IndicatorStyle.values()[index].name()+".png";net.minecraft.client.Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),c->System.out.println("V15_VISUAL capture="+name));index++;ticks=0;}
 else if(ticks==1&&index>=6&&index<8&&applied!=index){applied=index;boolean up=index==6;pending=CompletableFuture.runAsync(()->{var level=mc.getSingleplayerServer().overworld();var be=(ElevatorPartEntity)level.getBlockEntity(call);be.clearMarkers();be.toggleMarker(driver.above(7));ElevatorCallBlock.refreshPanel(level,call,be);check(be.callLayout==0,"Arbitrary-height middle link has both arrows");var player=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();double targetY=call.getY()+(up?.668:.394),feet=call.getY()-1;float pitch=(float)-Math.toDegrees(Math.atan2(targetY-(feet+player.getEyeHeight()),2.934));player.connection.teleport(call.getX()+.5,feet,call.getZ()-2,0,pitch);},mc.getSingleplayerServer());}
 else if(ticks==30&&index>=6&&index<8){check(mc.hitResult instanceof net.minecraft.world.phys.BlockHitResult h&&h.getBlockPos().equals(call)&&h.getDirection()==Direction.NORTH,"Crosshair reaches front arrow surface");var h=(net.minecraft.world.phys.BlockHitResult)mc.hitResult;check(com.sanctuarygames.createtransit.elevator.client.TouchCallPanelRenderer.directionAt(0,h.getLocation().y-call.getY())==(index==6?1:-1),"Actual native hit picks intended arrow");String name=index==6?"V15-hover-up.png":"V15-hover-down.png";net.minecraft.client.Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),c->System.out.println("V15_VISUAL capture="+name));index++;ticks=0;}
 else if(ticks==1&&index>=8&&index<10&&applied!=index){applied=index;boolean landing=index==8;pending=CompletableFuture.runAsync(()->{var d=(ElevatorDriveEntity)mc.getSingleplayerServer().overworld().getBlockEntity(driver);var cabin=d.model().entity();var eye=cabin.world(1.5,.125,landing?-1.35:.7);var target=cabin.world(.5,1.55,landing?-.875:.25);var player=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();double dx=target.x-eye.x,dz=target.z-eye.z,dy=target.y-eye.y-player.getEyeHeight();player.connection.teleport(eye.x,eye.y,eye.z,(float)Math.toDegrees(Math.atan2(-dx,dz)),(float)-Math.toDegrees(Math.atan2(dy,Math.hypot(dx,dz))));},mc.getSingleplayerServer());}
 else if(ticks==30&&index>=8&&index<10){String name=index==8?"V151-inset-landing.png":"V151-inset-cabin.png";net.minecraft.client.Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),c->System.out.println("V151_VISUAL capture="+name));index++;ticks=0;}
 else if(index>=10){System.out.println("PASS: V15 native full-resource hallway captures for six styles, terminal call fixture and actual crosshair hover on each arrow.");mc.stop();index=100;}
 }
}
